// Só analisa o que ainda não foi avisado. Chave da conversa parada inclui o id da última mensagem:
// se alguém escrever, a conversa "reabre" e pode ser avisada de novo se parar outra vez.
const sd = $getWorkflowStaticData('global');
sd.avisados = sd.avisados || {};
const cfg = $('Config').first().json;
const limite = Number(cfg.max_por_execucao) || 8;
const novos = $input.all().map((i) => i.json).filter((r) => r && r.chave && !sd.avisados[r.chave]);
return novos.slice(0, limite).map((r) => ({ json: r }));

// Pergunta para a IA SEM e-mail e telefone: ela só precisa do contexto da conversa.
const out = [];
for (const it of $input.all()) {
  const r = it.json, d = r.dados || {};
  const msgs = (d.mensagens || []).map((m) => '[' + m.quando + '] ' + m.quem + ': ' + (m.texto || '(sem texto)')).join('\n') || '(sem mensagens no chat)';
  const cab = r.tipo === 'proposta'
    ? 'Tipo: PROPOSTA sem resposta há ' + d.dias_parada + ' dia(s). A proposta foi enviada pelo ' + d.proposta_de + '. Preço: ' + d.preco + ' · Quantidade: ' + d.quantidade
    : 'Tipo: CONVERSA parada há ' + d.dias_parada + ' dia(s). A última mensagem foi do ' + d.ultimo_remetente + '. Total de mensagens: ' + d.n_msgs;
  out.push({ json: { ...r, prompt: cab + '\nProduto do anúncio: ' + (d.produto || 'não informado') + '\n\nÚltimas mensagens (da mais antiga para a mais recente):\n' + msgs } });
}
return out;

const limpo = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
const tel = (d) => {
  const n = String(d || '').replace(/\D/g, '');
  if (!n) return 'sem telefone';
  const l = n.startsWith('55') && n.length >= 12 ? n.slice(2) : n;
  return l.length === 11 ? '+55 (' + l.slice(0, 2) + ') ' + l.slice(2, 7) + '-' + l.slice(7)
       : l.length === 10 ? '+55 (' + l.slice(0, 2) + ') ' + l.slice(2, 6) + '-' + l.slice(6) : '+' + n;
};
const pessoa = (rotulo, p) => {
  p = p || {};
  return rotulo + ': ' + (limpo(p.nome) || 'sem nome') + ' · id ' + (p.id == null ? '?' : p.id) +
    '\n   ✉ ' + (limpo(p.email) || 'sem e-mail') + ' · 📞 ' + tel(p.telefone);
};
const sd = $getWorkflowStaticData('global');
sd.avisados = sd.avisados || {};
const linhas = $('Prepara pergunta para IA').all();
const respostas = $input.all();

function lerJson(txt) {
  if (txt && typeof txt === 'object') return txt;
  let s = String(txt || '').trim();
  const cerca = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (cerca) s = cerca[1].trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) s = s.slice(a, b + 1);
  try { return JSON.parse(s); } catch (e) { return null; }
}

const saida = [];
respostas.forEach((resp, i) => {
  const r = (linhas[i] || {}).json;
  if (!r) return;
  const d = r.dados || {};
  const falhouIA = !resp.json || resp.json.error;
  const ia = falhouIA ? null : lerJson(resp.json.text || resp.json.output || resp.json.response);
  // IA indisponível ou resposta ilegível: avisa mesmo assim (melhor sobrar aviso do que perder conversa).
  if (ia && ia.alertar === false) { sd.avisados[r.chave] = Date.now(); return; }

  const aguardando = r.tipo === 'proposta'
    ? (d.proposta_de === 'interessado' ? 'anunciante' : 'interessado')
    : (d.ultimo_remetente === 'anunciante' ? 'interessado' : 'anunciante');
  const quem = aguardando === 'anunciante' ? d.anunciante : d.interessado;
  const titulo = r.tipo === 'proposta'
    ? '📨 *Proposta sem resposta há ' + d.dias_parada + ' dias*'
    : '⏳ *Conversa parada há ' + d.dias_parada + ' dias*';
  const urg = ia && ia.urgencia ? ' · urgência ' + limpo(ia.urgencia) : '';
  const texto = [
    titulo,
    'Produto: ' + (limpo(d.produto) || 'não informado') + ' (anúncio #' + d.bid_id + ')',
    'Aguardando resposta do ' + aguardando + ': ' + (limpo((quem || {}).nome) || 'sem nome') + urg,
    ia && ia.resumo ? '🧠 ' + limpo(ia.resumo) : '🧠 (análise da IA indisponível)',
    pessoa('👤 Interessado', d.interessado),
    pessoa('🏷 Anunciante', d.anunciante),
  ].join('\n');
  saida.push({ json: { key: r.chave, text: texto } });
});
return saida;

const sd = $getWorkflowStaticData('global');
sd.avisados = sd.avisados || {};
const msgs = $('Interpreta e monta mensagem').all();
const res = $('Envia no grupo').all();
let ok = 0, falhas = 0;
res.forEach((r, i) => {
  const falhou = !r.json || r.json.error || (r.json.success === false);
  if (falhou) falhas++; else if (msgs[i]) { sd.avisados[msgs[i].json.key] = Date.now(); ok++; }
});
// guarda só os 1000 avisos mais recentes
const ks = Object.keys(sd.avisados);
if (ks.length > 1000) ks.sort((a, b) => sd.avisados[a] - sd.avisados[b]).slice(0, ks.length - 1000).forEach((k) => delete sd.avisados[k]);
return [{ json: { avisos_enviados: ok, falhas } }];

